    18  #ifndef UWS_TOPICTREE_H
    19  #define UWS_TOPICTREE_H
    20
    21  #include <map>
    22  #include <list>
    23  #include <iostream>
    24  #include <unordered_set>
    25  #include <utility>
    26  #include <memory>
    27  #include <unordered_map>
    28  #include <vector>
    29  #include <string_view>
    30  #include <functional>
    31  #include <set>
    32
    33  namespace uWS {
    34
    35  struct Subscriber;
    36
    37  struct Topic : std::unordered_set<Subscriber *> {
    38
    39      Topic(std::string_view topic) : name(topic) {
    40
    41      }
    42
    43      std::string name;
    44  };
    45
    46  struct Subscriber {
    47
    48      template <typename> friend struct TopicTree;
    49
    50  private:
    51      /* We use a factory */
    52      Subscriber() = default;
    53
    54      /* State of prev, next does not matter unless we are needsDrainage() since we are not in the list */
    55      Subscriber *prev, *next;
    56
    57      /* Any one subscriber can be part of at most 32 publishes before it needs a drain,
    58       * or whatever encoding of runs or whatever we might do in the future */
    59      uint16_t messageIndices[32];
    60
    61      /* This one matters the most, if it is 0 we are not in the list of drainableSubscribers */
    62      unsigned char numMessageIndices = 0;
    63
    64  public:
    65
    66      /* We have a list of topics we subscribe to (read by WebSocket::iterateTopics) */
    67      std::set<Topic *> topics;
    68
    69      /* User data */
    70      void *user;
    71
    72      bool needsDrainage() {
    73          return numMessageIndices;
    74      }
    75  };
    76
    77  template <typename T>
    78  struct TopicTree {
    79
    80      enum IteratorFlags {
    81          LAST = 1,
    82          FIRST = 2
    83      };
    84
    85  private:
    86      /* Whomever is iterating this topic is locked to not modify its own list */
    87      Subscriber *iteratingSubscriber = nullptr;
    88
    89      /* The drain callback must not publish, unsubscribe or subscribe.
    90       * It must only cork, uncork, send, write */
    91      std::function<bool(Subscriber *, T &, IteratorFlags)> cb;
    92
    93      /* The topics */
    94      std::unordered_map<std::string_view, std::unique_ptr<Topic>> topics;
    95
    96      /* List of subscribers that needs drainage */
    97      Subscriber *drainableSubscribers = nullptr;
    98
    99      /* Palette of outgoing messages, up to 64k */
   100      std::vector<T> outgoingMessages;
   101
   102      void checkIteratingSubscriber(Subscriber *s) {
   103          /* Notify user that they are doing something wrong here */
   104          if (iteratingSubscriber == s) {
   105              std::cerr << "Error: WebSocket must not subscribe or unsubscribe to topics while iterating its topics!" << std::endl;
   106              std::terminate();
   107          }
   108      }
   109
   110      /* Warning: does NOT unlink from drainableSubscribers or modify next, prev. */
   111      void drainImpl(Subscriber *s) {
   112          /* Before we call cb we need to make sure this subscriber will not report needsDrainage()
   113           * since WebSocket::send will call drain from within the cb in that case.*/
   114          int numMessageIndices = s->numMessageIndices;
   115          s->numMessageIndices = 0;
   116
   117          /* Then we emit cb */
   118          for (int i = 0; i < numMessageIndices; i++) {
   119              T &outgoingMessage = outgoingMessages[s->messageIndices[i]];
   120
   121              int flags = (i == numMessageIndices - 1) ? LAST : 0;
   122
   123              /* Returning true will stop drainage short (such as when backpressure is too high) */
   124              if (cb(s, outgoingMessage, (IteratorFlags)(flags | (i == 0 ? FIRST : 0)))) {
   125                  break;
   126              }
   127          }
   128      }
   129
   130  public:
   131
   132      TopicTree(std::function<bool(Subscriber *, T &, IteratorFlags)> cb) : cb(cb) {
   133
   134      }
   135
   136      /* Returns nullptr if not found */
   137      Topic *lookupTopic(std::string_view topic) {
   138          auto it = topics.find(topic);
   139          if (it == topics.end()) {
   140              return nullptr;
   141          }
   142          return it->second.get();
   143      }
   144
   145      /* Subscribe fails if we already are subscribed */
   146      bool subscribe(Subscriber *s, std::string_view topic) {
   147          /* Notify user that they are doing something wrong here */
   148          checkIteratingSubscriber(s);
   149
   150          /* Lookup or create new topic */
   151          Topic *topicPtr = lookupTopic(topic);
   152          if (!topicPtr) {
   153              Topic *newTopic = new Topic(topic);
   154              topics.insert({std::string_view(newTopic->name.data(), newTopic->name.length()), std::unique_ptr<Topic>(newTopic)});
   155              topicPtr = newTopic;
   156          }
   157
   158          /* Insert us in topic, insert topic in us */
   159          auto [it, inserted] = s->topics.insert(topicPtr);
   160          if (!inserted) {
   161              return false;
   162          }
   163          topicPtr->insert(s);
   164
   165          /* Success */
   166          return true;
   167      }
   168
   169      /* Returns ok, last */
   170      std::pair<bool, bool> unsubscribe(Subscriber *s, std::string_view topic) {
   171          /* Notify user that they are doing something wrong here */
   172          checkIteratingSubscriber(s);
   173
   174          /* Lookup topic */
   175          Topic *topicPtr = lookupTopic(topic);
   176          if (!topicPtr) {
   177              /* If the topic doesn't exist we are assumed to still be subscribers of something */
   178              return {false, false};
   179          }
   180
   181          /* Erase from our list first */
   182          if (s->topics.erase(topicPtr) == 0) {
   183              return {false, false};
   184          }
   185
   186          /* Remove us from topic */
   187          topicPtr->erase(s);
   188
   189          /* If there is no subscriber to this topic, remove it */
   190          if (!topicPtr->size()) {
   191              /* Unique_ptr deletes the topic */
   192              topics.erase(topic);
   193          }
   194
   195          /* If we don't hold any topics we are to be freed altogether */
   196          return {true, topics.size() == 0};
   197      }
   198
   199      /* Factory function for creating a Subscriber */
   200      Subscriber *createSubscriber() {
   201          return new Subscriber();
   202      }
   203
   204      /* This is used to end a Subscriber, before freeing it */
   205      void freeSubscriber(Subscriber *s) {
   206
   207          /* I guess we call this one even if we are not subscribers */
   208          if (!s) {
   209              return;
   210          }
   211
   212          /* For all topics, unsubscribe */
   213          for (Topic *topicPtr : s->topics) {
   214              /* If we are the last subscriber, simply remove the whole topic */
   215              if (topicPtr->size() == 1) {
   216                  topics.erase(topicPtr->name);
   217              } else {
   218                  /* Otherwise just remove us */
   219                  topicPtr->erase(s);
   220              }
   221          }
   222
   223          /* We also need to unlink us */
   224          if (s->needsDrainage()) {
   225              if (s->prev) {
   226                  s->prev->next = s->next;
   227              }
   228              if (s->next) {
   229                  s->next->prev = s->prev;
   230              }
   231              /* If we are the head, then we also need to reset the head */
   232              if (drainableSubscribers == s) {
   233                  drainableSubscribers = nullptr;
   234              }
   235          }
   236
   237          delete s;
   238      }
   239
   240      /* Mainly used by WebSocket::send to drain one socket before sending */
   241      void drain(Subscriber *s) {
   242          /* The list is undefined and cannot be touched unless needsDrainage(). */
   243          if (s->needsDrainage()) {
   244              /* This function differs from drainImpl by properly unlinking
   245              * the subscriber from drainableSubscribers. drainImpl does not. */
   246              if (s->prev) {
   247                  s->prev->next = s->next;
   248              }
   249              if (s->next) {
   250                  s->next->prev = s->prev;
   251              }
   252              /* If we are the head, then we also need to reset the head */
   253              if (drainableSubscribers == s) {
   254                  drainableSubscribers = nullptr;
   255              }
   256
   257              /* This one always resets needsDrainage before it calls any cb's.
   258               * Otherwise we would stackoverflow when sending after publish but before drain. */
   259              drainImpl(s);
   260          }
   261      }
   262
   263      /* Called everytime we call send, to drain published messages so to sync outgoing messages */
   264      void drain() {
   265          if (drainableSubscribers) {
   266              /* Drain one socket a time */
   267              for (Subscriber *s = drainableSubscribers; s; s = s->next) {
   268                  /* Instead of unlinking every single subscriber, we just leave the list undefined
   269                   * and reset drainableSubscribers ptr below. */
   270                  drainImpl(s);
   271              }
   272              /* Drain always clears drainableSubscribers and outgoingMessages */
   273              drainableSubscribers = nullptr;
   274              outgoingMessages.clear();
   275          }
   276      }
   277
   278      /* Linear in number of affected subscribers */
   279      bool publish(Subscriber *sender, std::string_view topic, T &&message) {
   280          /* Do we even have this topic? */
   281          auto it = topics.find(topic);
   282          if (it == topics.end()) {
   283              return false;
   284          }
   285
   286          /* If we have more than 65k messages we need to drain every socket. */
   287          if (outgoingMessages.size() == UINT16_MAX) {
   288              /* If there is a socket that is currently corked, this will be ugly as all sockets will drain
   289               * to their own backpressure */
   290              drain();
   291          }
   292
   293          /* For all subscribers in topic */
   294          for (Subscriber *s : *it->second) {
   295
   296              /* If we are sender then ignore us */
   297              if (sender != s) {
   298
   299                  /* If we already have too many outgoing messages on this subscriber, drain it now */
   300                  if (s->numMessageIndices == 32) {
   301                      /* This one does not need to check needsDrainage here but still does. */
   302                      drain(s);
   303                  }
   304
   305                  /* Finally we can continue */
   306                  s->messageIndices[s->numMessageIndices++] = (uint16_t)outgoingMessages.size();
   307                  /* First message adds subscriber to list of drainable subscribers */
   308                  if (s->numMessageIndices == 1) {
   309                      /* Insert us in the head of drainable subscribers */
   310                      s->next = drainableSubscribers;
   311                      s->prev = nullptr;
   312                      if (s->next) {
   313                          s->next->prev = s;
   314                      }
   315                      drainableSubscribers = s;
   316                  }
   317              }
   318          }
   319
   320          /* Push this message and return with success */
   321          outgoingMessages.emplace_back(message);
   322          return true;
   323      }
   324
   325  };
   326
   327  }
   328
   329  #endif
